sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    var desc = '';
    var hrTask = new GlideRecord('sn_hr_core_task');

    //build description from HIRA Item information
    desc += 'Work Task & Description: ' + current.work_task_description + '\n';
    desc += 'Hazard Category: ' + current.hazard_category + ' - ' + current.hazard_subcategory + '\n';
    desc += 'Hazard Description: ' + current.hazard_description + '\n';
    desc += 'Recommended Action: ' + current.recommended_action + '\n';
    desc += 'Start Date: ' + current.start_date + '\n';
    desc += 'Is there a training component? ' + current.training.getDisplayValue() + '\n';
    desc += 'Comment: ' + current.comment;


    hrTask.initialize();
    hrTask.parent = current.hira_case;
    hrTask.assigned_to = current.hira_case.manager_name;
    hrTask.hr_task_type = 'follow_up';
    hrTask.task_type = 'hr_task';
    hrTask.short_description = 'HIRA recommneded Action. Start Date: ' + current.start_date;
    hrTask.description = desc;
    hrTask.follow_up = current.start_date;

    var sys_id = hrTask.insert();

    if (sys_id) { //did the record save?
        current.hr_task = sys_id; //link the HR Task to the record.
    }

})(current, previous);
